const BANDS = [
  "All",
  "Pre-Band I",
  "Band I Core I",
  "Band I Core II",
  "Band II Core I",
  "Band II Core II",
  "Band III List A",
  "Band III List B",
  "Band III List C",
  "Band III List D",
];

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function pickRandom(arr, n) {
  return shuffle(arr).slice(0, n);
}

function generateExam() {
  // Only use words that have both english definition and pos
  const pool = exerciseWords.filter(w => w.englishDefinition && w.pos && w.englishDefinition.length > 3);
  const exercises = [];

  for (let i = 0; i < 10; i++) {
    // Pick 3 answer words
    const remaining = pool.filter(w => !exercises.some(ex => ex.answers.some(a => a.entry === w.entry)));
    const answers = pickRandom(remaining, 3);

    // Pick 3 distractors (different entries, different band/pos ideally)
    const distPool = pool.filter(w =>
      !answers.some(a => a.entry === w.entry) &&
      !exercises.some(ex => ex.answers.some(a => a.entry === w.entry))
    );
    const distractors = pickRandom(distPool, 3);

    // 6 words sorted alphabetically
    const sixWords = [...answers, ...distractors].sort((a, b) =>
      a.entry.toLowerCase().localeCompare(b.entry.toLowerCase())
    );

    // 3 definitions randomized
    const definitions = shuffle(answers.map(a => ({
      entry: a.entry,
      definition: a.englishDefinition,
    })));

    exercises.push({ words: sixWords, answers, definitions });
  }

  return exercises;
}

function PosTag({ pos }) {
  if (!pos) return null;
  return (
    <span style={{
      fontSize: "10px",
      fontFamily: "Times New Roman, serif",
      color: "#888",
      border: "1px solid #ccc",
      borderRadius: "2px",
      padding: "0 3px",
      marginLeft: "4px",
      verticalAlign: "middle",
    }}>{pos}</span>
  );
}

function GlossaryModal({ onClose }) {
  const [search, setSearch] = useState("");
  const [band, setBand] = useState("All");

  const filtered = useMemo(() => {
    let list = glossaryWords;
    if (band !== "All") list = list.filter(w => w.band === band);
    if (search.trim()) {
      const q = search.toLowerCase();
      list = list.filter(w =>
        w.entry.toLowerCase().includes(q) ||
        (w.hebrewDefinition && w.hebrewDefinition.includes(q)) ||
        (w.englishDefinition && w.englishDefinition.toLowerCase().includes(q))
      );
    }
    return [...list].sort((a, b) => a.entry.toLowerCase().localeCompare(b.entry.toLowerCase()));
  }, [search, band]);

  return (
    <div
      className="modal-overlay"
      style={{
        position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)",
        zIndex: 1000, display: "flex", alignItems: "center", justifyContent: "center",
      }}
      onClick={onClose}
    >
      <div
        className="modal-window"
        style={{
          background: "#fff", borderRadius: "4px", maxWidth: "860px", width: "95vw",
          maxHeight: "90vh", display: "flex", flexDirection: "column",
          border: "1px solid #d8b4b8", overflow: "hidden",
        }}
        onClick={e => e.stopPropagation()}
      >
        {/* Header */}
        <div style={{
          display: "flex", justifyContent: "space-between", alignItems: "center",
          padding: "16px 24px 12px", borderBottom: "1px solid #e8d0d2",
        }}>
          <h2 style={{ fontFamily: "David Libre, David, serif", fontSize: "20px", margin: 0, color: "#3a2a2c" }}>
            מילון מונחים ללימוד
          </h2>
          <button
            onClick={onClose}
            style={{
              background: "none", border: "none", cursor: "pointer",
              fontFamily: "Times New Roman, serif", fontSize: "22px", color: "#888",
              lineHeight: 1, padding: "0 4px",
            }}
          >X</button>
        </div>

        {/* Search */}
        <div style={{ padding: "12px 24px", borderBottom: "1px solid #f0e0e2" }}>
          <input
            type="text"
            placeholder="Search English or Hebrew..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            style={{
              width: "100%", boxSizing: "border-box",
              fontFamily: "Times New Roman, serif", fontSize: "14px",
              border: "1px solid #d8b4b8", borderRadius: "3px", padding: "7px 10px",
              outline: "none", color: "#222",
            }}
          />
        </div>

        {/* Band filter */}
        <div style={{ padding: "10px 24px", borderBottom: "1px solid #f0e0e2", display: "flex", flexWrap: "wrap", gap: "6px" }}>
          {BANDS.map(b => (
            <button
              key={b}
              onClick={() => setBand(b)}
              style={{
                fontFamily: "Times New Roman, serif", fontSize: "12px",
                padding: "4px 10px", borderRadius: "20px", cursor: "pointer",
                border: band === b ? "1px solid #c48890" : "1px solid #e0c4c8",
                background: band === b ? "#e8b4b8" : "#fff",
                color: band === b ? "#fff" : "#6a4a50",
                fontWeight: band === b ? "600" : "400",
                transition: "all 0.15s",
              }}
            >{b}</button>
          ))}
        </div>

        {/* Count */}
        <div style={{ padding: "6px 24px", fontSize: "12px", color: "#999", fontFamily: "Times New Roman, serif" }}>
          {filtered.length} {filtered.length === 1 ? "word" : "words"}
        </div>

        {/* List */}
        <div style={{ overflowY: "auto", flex: 1, padding: "0 24px 16px" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontFamily: "Times New Roman, serif" }}>
            <thead>
              <tr style={{ borderBottom: "2px solid #e8d0d2", position: "sticky", top: 0, background: "#fff" }}>
                <th style={thStyle}>Entry</th>
                <th style={{...thStyle, width: "60px"}}>PoS</th>
                <th style={thStyle}>Definition</th>
                <th style={{...thStyle, textAlign: "right"}}>עברית</th>
                <th style={{...thStyle, width: "120px"}}>Band</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map((w, i) => (
                <tr key={i} style={{ borderBottom: "1px solid #f5e8ea", background: i % 2 === 0 ? "#fff" : "#fdf8f8" }}>
                  <td style={{ padding: "6px 8px", fontSize: "14px", color: "#222", fontWeight: "500" }}>{w.entry}</td>
                  <td style={{ padding: "6px 8px", fontSize: "12px", color: "#888" }}>{w.pos}</td>
                  <td style={{ padding: "6px 8px", fontSize: "13px", color: "#444" }}>{w.englishDefinition || "—"}</td>
                  <td style={{ padding: "6px 8px", fontSize: "13px", color: "#3a2a2c", textAlign: "right", direction: "rtl" }}>{w.hebrewDefinition || "—"}</td>
                  <td style={{ padding: "6px 8px", fontSize: "11px", color: "#a07070" }}>{w.band}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

const thStyle = {
  padding: "8px 8px",
  fontFamily: "Times New Roman, serif",
  fontSize: "12px",
  color: "#7a5055",
  textAlign: "left",
  fontWeight: "600",
  textTransform: "uppercase",
  letterSpacing: "0.05em",
};

export default function App() {
  const [exercises, setExercises] = useState(null);
  const [showGlossary, setShowGlossary] = useState(false);

  const handleGenerate = useCallback(() => {
    setExercises(generateExam());
  }, []);

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=David+Libre:wght@400;700&display=swap');

        * { box-sizing: border-box; margin: 0; padding: 0; }
        body { background: #f9f4f5; font-family: Times New Roman, serif; }

        .btn-primary {
          background: #e8b4b8;
          color: #fff;
          border: none;
          border-radius: 6px;
          padding: 10px 22px;
          font-family: David Libre, David, serif;
          font-size: 15px;
          cursor: pointer;
          letter-spacing: 0.01em;
          transition: background 0.15s;
        }
        .btn-primary:hover { background: #d9999e; }

        .exam-sheet {
          background: #fff;
          max-width: 800px;
          margin: 0 auto;
          padding: 48px 52px;
          border: 1px solid #e8d8da;
        }

        .exam-title {
          font-family: David Libre, David, serif;
          font-size: 20px;
          text-align: center;
          margin-bottom: 32px;
          color: #111;
          letter-spacing: 0.02em;
        }

        .exercise-block {
          margin-bottom: 32px;
          page-break-inside: avoid;
        }

        .exercise-heading {
          font-family: Times New Roman, serif;
          font-size: 13px;
          font-weight: bold;
          margin-bottom: 10px;
          color: #111;
          border-bottom: 1px solid #e0c8ca;
          padding-bottom: 4px;
        }

        .exercise-columns {
          display: grid;
          grid-template-columns: 1fr 1fr;
          gap: 0 40px;
        }

        .word-list, .def-list {
          list-style: none;
          padding: 0;
        }

        .word-item, .def-item {
          font-family: Times New Roman, serif;
          font-size: 13px;
          color: #111;
          padding: 3px 0;
          border-bottom: 1px dotted #e0d0d2;
          display: flex;
          align-items: baseline;
          gap: 6px;
        }

        .word-num, .def-letter {
          font-size: 11px;
          color: #888;
          min-width: 16px;
          font-style: normal;
        }

        .def-blank {
          font-family: Times New Roman, serif;
          font-size: 12px;
          color: #333;
          letter-spacing: 0.05em;
        }

        .answer-key {
          margin-top: 48px;
          border-top: 2px solid #e0c8ca;
          padding-top: 16px;
          transform: rotate(180deg);
          display: block;
          page-break-before: always;
        }

        .answer-key-title {
          font-family: Times New Roman, serif;
          font-size: 11px;
          text-align: center;
          color: #888;
          margin-bottom: 8px;
          letter-spacing: 0.08em;
          text-transform: uppercase;
        }

        .answer-key-grid {
          display: grid;
          grid-template-columns: repeat(5, 1fr);
          gap: 4px 12px;
        }

        .answer-key-item {
          font-family: Times New Roman, serif;
          font-size: 11px;
          color: #444;
        }

        @media print {
          body { background: #fff !important; }
          .no-print { display: none !important; }
          .modal-overlay, .modal-window, .modal-overlay * { display: none !important; }
          .exam-sheet { border: none; padding: 20px 24px; max-width: 100%; margin: 0; }
          .exercise-block { page-break-inside: avoid; }
          .answer-key { display: block !important; }
        }

        @media screen {
          .app-shell {
            min-height: 100vh;
            padding: 32px 16px;
          }
        }
      `}</style>

      <div className="app-shell">
        {/* Controls - hidden on print */}
        <div className="no-print" style={{ maxWidth: "800px", margin: "0 auto 28px", display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: "12px" }}>
          <div style={{ fontFamily: "David Libre, David, serif", fontSize: "22px", color: "#3a2a2c", letterSpacing: "0.01em" }}>
            Bagrut Vocabulary Practice
          </div>
          <div style={{ display: "flex", gap: "10px", alignItems: "center", flexWrap: "wrap" }}>
            <button className="btn-primary" onClick={handleGenerate}>חולל מבחן חדש</button>
            {exercises && (
              <button className="btn-primary" onClick={() => window.print()}>הדפס מבחן</button>
            )}
            <button
              onClick={() => setShowGlossary(true)}
              style={{
                background: "none", border: "none", cursor: "pointer",
                fontFamily: "David Libre, David, serif", fontSize: "14px",
                color: "#b87070", textDecoration: "underline", textUnderlineOffset: "3px",
              }}
            >מילון מונחים ללימוד</button>
          </div>
        </div>

        {/* Exam Sheet */}
        {exercises ? (
          <div className="exam-sheet">
            <h1 className="exam-title">מבחן אוצר מילים — Module E</h1>

            {exercises.map((ex, idx) => (
              <div key={idx} className="exercise-block">
                <div className="exercise-heading">Exercise {idx + 1}</div>
                <div className="exercise-columns">
                  {/* Left: 6 words */}
                  <ul className="word-list">
                    {ex.words.map((w, wi) => (
                      <li key={wi} className="word-item">
                        <span className="word-num">{wi + 1}.</span>
                        <span>{w.entry}</span>
                        <span style={{ fontSize: "10px", color: "#aaa", marginLeft: "2px" }}>({w.pos})</span>
                      </li>
                    ))}
                  </ul>
                  {/* Right: 3 definitions */}
                  <ul className="def-list">
                    {ex.definitions.map((d, di) => (
                      <li key={di} className="def-item" style={{ alignItems: "flex-start", flexDirection: "column", paddingBottom: "8px", marginBottom: "2px" }}>
                        <span className="def-blank">_____ </span>
                        <span style={{ fontSize: "13px", color: "#111", lineHeight: "1.4", marginTop: "1px" }}>{d.definition}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            ))}

            {/* Upside-down Answer Key */}
            <div className="answer-key">
              <div className="answer-key-title">Answer Key</div>
              <div className="answer-key-grid">
                {exercises.map((ex, idx) => {
                  // For each definition, find the word number in ex.words
                  const answers = ex.definitions.map(d => {
                    const wordIdx = ex.words.findIndex(w => w.entry === d.entry);
                    return `Ex.${idx + 1}: ${wordIdx + 1}`;
                  });
                  return answers.map((a, ai) => (
                    <span key={`${idx}-${ai}`} className="answer-key-item">{a}</span>
                  ));
                })}
              </div>
            </div>
          </div>
        ) : (
          <div style={{
            maxWidth: "800px", margin: "0 auto", padding: "72px 32px",
            textAlign: "center", color: "#b09095",
            fontFamily: "David Libre, David, serif", fontSize: "16px", lineHeight: "1.8",
            background: "#fff", border: "1px solid #e8d8da",
          }}>
            <div style={{ fontSize: "28px", marginBottom: "16px", color: "#d8a0a8" }}>לחצי על &ldquo;חולל מבחן חדש&rdquo; להתחיל</div>
            <div style={{ fontSize: "14px", color: "#c0a0a5", fontFamily: "Times New Roman, serif" }}>
              10 exercises · 6 words each · 3 definitions to match
            </div>
          </div>
        )}
      </div>

      {showGlossary && <GlossaryModal onClose={() => setShowGlossary(false)} />}
    </>
  );
}
